   // https://www.instagram.com/samuel_yan_1990/

let left_x, right_x, top_y, bottom_y, resolution;
let num_colums, num_rows;
let grid = [];
let default_angle, angle;
let space;
let zoff = 0;
var inc = 0.05;
var scl = 6;

function setup() {
  //frameRate(30);
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  left_x = int(width * -0.5);
  right_x = int(width * 1.5);
  top_y = int(height * -0.5);
  bottom_y = int(height * 1.5);
  resolution = 10;
  num_columns = (right_x - left_x) / resolution;
  num_rows = (bottom_y - top_y) / resolution;
  space = 2;
  for (let x = left_x; x < right_x; x++) {
    grid[x] = [];
    for (let y = top_y; y < bottom_y; y++) {
      let angle = (y / bottom_y) * PI * 5.2 - 2.5;
      grid[x][y] = angle + 10*random(-HALF_PI / space,HALF_PI / space);
    }
  }
  // pixelDensity(5);
  background(0, 0, 95, 100);
}

function draw() {
  //background(0, 0, 95, 100);
  let x = random(0, width);
  let y = random(0, height);
  let step_length = random(14, 18);
  let weight = random(0.5, 0.8);
  strokeWeight(weight);
  strokeCap(SQUARE);
  noFill();
  stroke(70, 95, 65, random(15, 45));

  for (let x = 0; x < num_columns; x++) {
    for (let y = 0; y < num_rows; y++) {
      //stroke(10,95,95,100);
      let point_x = x * resolution;
      let point_y = y * resolution;
      push();
      translate(point_x, point_y);
      rotate(grid[x][y]);
      //circle(point_x, point_y,2);
      rect(0, 0, -random(8) , random(8) );
      pop();
    }
  }
}

